<?php
$p='feature_showcase'; $eyebrow=get_field("{$p}_eyebrow"); $title=get_field("{$p}_title"); $intro=get_field("{$p}_intro"); $image=get_field("{$p}_image"); $features=get_field("{$p}_features")?:[]; $settings=get_field("{$p}_section_settings"); $sectionId=inkwell_component_id($block??[],'feature-showcase'); $split=(int)ceil(count($features)/2); $left=array_slice($features,0,$split); $right=array_slice($features,$split);
$renderFeatures=function($items,$side)use($p){foreach($items as $item){?><article class="flex gap-4 <?php echo $side==='left'?'lg:flex-row-reverse lg:text-right':'';?>"><span class="shrink-0 text-[#0867f2]"><?php echo inkwell_component_icon($item["{$p}_feature_icon"]??'check','h-7 w-7');?></span><div><?php if(!empty($item["{$p}_feature_title"])){?><h3 class="text-sm font-semibold"><?php echo esc_html($item["{$p}_feature_title"]);?></h3><?php }?><?php if(!empty($item["{$p}_feature_copy"])){?><p class="mt-1 text-sm leading-5 opacity-70"><?php echo wp_kses_post($item["{$p}_feature_copy"]);?></p><?php }?></div></article><?php }};
?>
<section id="<?php echo esc_attr($sectionId);?>" class="feature-showcase px-6 <?php echo esc_attr(inkwell_component_section_classes($settings,$p));?>"><div class="mx-auto <?php echo esc_attr(inkwell_component_container_class($settings,$p));?>"><header class="mx-auto mb-10 max-w-2xl text-center"><?php if($eyebrow){?><p class="mb-3 text-xs font-semibold uppercase tracking-[.14em] opacity-60"><?php echo esc_html($eyebrow);?></p><?php }?><?php if($title){?><h2 class="text-[clamp(32px,4vw,48px)] font-semibold leading-tight"><?php echo esc_html($title);?></h2><?php }?><?php if($intro){?><p class="mx-auto mt-4 max-w-xl leading-7 opacity-70"><?php echo wp_kses_post($intro);?></p><?php }?></header><div class="grid items-center gap-9 lg:grid-cols-[1fr_1.35fr_1fr]"><div class="order-2 space-y-8 lg:order-1"><?php $renderFeatures($left,'left');?></div><div class="order-1 flex min-h-[320px] items-end justify-center lg:order-2"><?php echo inkwell_component_image($image,'large','max-h-[430px] w-full object-contain');?></div><div class="order-3 space-y-8"><?php $renderFeatures($right,'right');?></div></div></div></section>
